import SwiftUI

struct ScreenHeader: View { let icon: String; let title: String; let subtitle: String; var trailing: AnyView? = nil; var body: some View { HStack(alignment: .center, spacing: 14) { ZStack { Circle().fill(LinearGradient(colors: [.orange, .pink], startPoint: .topLeading, endPoint: .bottomTrailing)).frame(width: 56, height: 56).shadow(color: .orange.opacity(0.35), radius: 18); Image(systemName: icon).font(.system(size: 26, weight: .bold)).foregroundStyle(.white) }; VStack(alignment: .leading, spacing: 2) { Text(title).font(.system(size: 34, weight: .bold, design: .rounded)); Text(subtitle).font(.subheadline).foregroundStyle(.secondary) }; Spacer(); trailing }.padding(.horizontal, 22).padding(.top, 8).padding(.bottom, 14) } }
struct GlassCard<Content: View>: View { var padding: CGFloat = 18; @ViewBuilder var content: () -> Content; var body: some View { content().padding(padding).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 26, style: .continuous)).overlay(RoundedRectangle(cornerRadius: 26).stroke(LinearGradient(colors: [.purple.opacity(0.65), .pink.opacity(0.2)], startPoint: .topLeading, endPoint: .bottomTrailing), lineWidth: 1)).shadow(color: .purple.opacity(0.14), radius: 16, y: 8) } }
struct PrimaryButton: View { let title: String; let icon: String; var color: [Color] = [.orange, .pink]; let action: () -> Void; var body: some View { Button(action: action) { HStack(spacing: 10) { Image(systemName: icon).font(.title3.weight(.bold)); Text(title).font(.headline.weight(.bold)); Image(systemName: "sparkles").font(.caption) }.frame(maxWidth: .infinity).padding(.vertical, 16).foregroundStyle(.white).background(LinearGradient(colors: color, startPoint: .leading, endPoint: .trailing), in: Capsule()).shadow(color: color[0].opacity(0.35), radius: 14, y: 6) } }
struct MetricCard: View { let icon: String; let value: String; let label: String; var color: Color = .purple; var body: some View { VStack(alignment: .leading, spacing: 8) { Image(systemName: icon).foregroundStyle(color).font(.title3); Text(value).font(.title2.weight(.bold)); Text(label).font(.caption).foregroundStyle(.secondary) }.frame(maxWidth: .infinity, alignment: .leading).padding(15).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 20)) } }
struct SectionTitle: View { let title: String; var trailing: String?; var body: some View { HStack { Text(title).font(.title2.weight(.bold)); Spacer(); if let trailing { Text(trailing).font(.subheadline.weight(.semibold)).foregroundStyle(.purple) } }.padding(.horizontal, 22).padding(.top, 12) } }
